});

pm.test("Shipping address validation errors are returned", function () {
    const responseBody = pm.response.json();

    pm.expect(responseBody.details).to.be.an("array");

    pm.expect(responseBody.details)
        .to.include("street is required");

    pm.expect(responseBody.details)
        .to.include("city is required");

    pm.expect(responseBody.details)
        .to.include("state is required");

    pm.expect(responseBody.details)
        .to.include("postalCode is required");

    pm.expect(responseBody.details)
        .to.include("country is required");
});

